// Close is permitted only at MAIN, and only after a completed lookup in this
// session showing an ACCEPTED approval by a PERSON for the same work order
// and site within the last hour. Two policies, one per approval source,
// because temporal blocks have no ||.

@id("close-with-nimbrel-approval")
permit (principal, action == Drupe::Action::"MaintData___close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"Nimbrel___get_approval"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.decision: Drupe::decision::"ACCEPTED",
    output.approver_kind: Drupe::approver_kind::"PERSON"
  }
};

@id("close-with-tolvick-approval")
permit (principal, action == Drupe::Action::"MaintData___close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"Tolvick___get_approval"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.decision: Drupe::decision::"ACCEPTED",
    output.approver_kind: Drupe::approver_kind::"PERSON"
  }
};

// Read-only lookups. The two approval lookups must be permitted so that
// their responses are recorded and can satisfy the close conditions.
@id("allow-read-only-lookups")
permit (principal, action in [
    Drupe::Action::"Nimbrel___get_approval",
    Drupe::Action::"Tolvick___get_approval",
    Drupe::Action::"MaintData___get_workorder",
    Drupe::Action::"MaintData___get_workorder_tasks",
    Drupe::Action::"MaintData___get_workorder_costs",
    Drupe::Action::"MaintData___get_workorder_actuals_vs_planned",
    Drupe::Action::"MaintData___get_workorder_kpis",
    Drupe::Action::"MaintData___list_workorders",
    Drupe::Action::"MaintData___get_my_assigned_workorders",
    Drupe::Action::"MaintData___get_schedule_calendar",
    Drupe::Action::"MaintData___get_failure_codes"
  ], resource);

// The agent may never approve work orders itself.
@id("never-approve")
forbid (principal, action == Drupe::Action::"MaintData___approve_workorder", resource);

// No other tool (generate, update, assign, cancel) has a permit, so each is denied by default.
```

